const tz = 'America/Montevideo';
const now = DateTime.now().setZone(tz).startOf('day');
const daysSinceSat = (now.weekday + 1) % 7; // 0=Sáb..6=Vie
const sabado = now.minus({ days: daysSinceSat });
const lunes = sabado.minus({ days: 5 });
return [{
  json: {
    desde: lunes.toISODate(),
    hasta: sabado.toISODate(),
    semanaISO: sabado.toFormat("kkkk-'W'WW"),
    actualizado: DateTime.now().setZone(tz).toFormat('yyyy-MM-dd HH:mm')
  }
}];

const helpers = this.helpers;
