const API = 'https://api.dentalink.healthatom.com/api/v1';
const meta = $input.first().json;

async function fetchAll(startUrl) {
  const out = [];
  let url = startUrl;
  let guard = 0;
  while (url && guard < 500) {
    guard++;
    const resp = await helpers.httpRequest({ method: 'GET', url, headers: { Authorization: token }, json: true });
    const data = (resp && Array.isArray(resp.data)) ? resp.data : [];
    out.push(...data);
    const next = (resp && resp.links) ? resp.links.next : null;
    if (!next || next === url || data.length === 0) break;
    url = next;
  }
  return out;
}

