const root = $input.first().json;
const meta = root.meta;
const sucursales = root.sucursales || [];
const citas = root.citas || [];

// Universo 'Agendadas' = {7,28,8,19,14} + Atendido(2)
const AGENDADA = new Set([7, 28, 8, 19, 14, 2]);

const buckets = {};
for (const s of sucursales) {
  buckets[String(s.id)] = { Sucursal: s.nombre || ('Sucursal ' + s.id), agendadas: 0, atendidos: 0, noAsistio: 0 };
}
for (const c of citas) {
  const sid = String(c.id_sucursal);
  if (!buckets[sid]) buckets[sid] = { Sucursal: 'Sucursal ' + sid, agendadas: 0, atendidos: 0, noAsistio: 0 };
  const est = Number(c.id_estado);
  if (AGENDADA.has(est)) buckets[sid].agendadas++;
  if (est === 2) buckets[sid].atendidos++;
  if (est === 8) buckets[sid].noAsistio++;
}

const r1 = (n) => Math.round(n * 10) / 10;
const rows = Object.values(buckets).map((b) => ({
  json: {
    Semana: meta.semanaISO,
    Desde: meta.desde,
    Hasta: meta.hasta,
    Sucursal: b.Sucursal,
    Agendadas: b.agendadas,
    Atendidos: b.atendidos,
    'No asistió': b.noAsistio,
    '% Atendidos': b.agendadas > 0 ? r1(b.atendidos / b.agendadas * 100) : 0,
    '% Inasistencia': b.agendadas > 0 ? r1(b.noAsistio / b.agendadas * 100) : 0,
    Actualizado: meta.actualizado
  }
}));
rows.sort((a, b) => String(a.json.Sucursal).localeCompare(String(b.json.Sucursal)));
return rows;
